package br.com.eventflow.model; import jakarta.persistence.*; import java.time.LocalDateTime; import java.math.BigDecimal; @Entity @Table(name="pedidos") public class Pedido { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public LocalDateTime data=LocalDateTime.now(); public Integer quantidade; public BigDecimal valorTotal; public String status; @ManyToOne public Usuario participante; @ManyToOne public LoteIngresso loteIngresso; }